const items = $input.all();

// En tu versión, cuando no hay eventos Google Calendar devuelve [ {} ]
// y cuando hay eventos devuelve un item por cada evento con datos (summary, start, end, etc.)

let eventos = [];

items.forEach(i => {
  const ev = i.json || {};

  // Caso 1: cada item ya es un evento real
  if (ev.summary || ev.start || ev.end) {
    eventos.push(ev);
  }

  // Caso 2: el nodo devuelve arrays internos (por si cambia en otra operación)
  if (Array.isArray(ev.items)) {
    eventos = eventos.concat(ev.items);
  }
  if (Array.isArray(ev.events)) {
    eventos = eventos.concat(ev.events);
  }
});

console.log('=== DEBUG comprobar_disponibilidad ===');
console.log('Total items recibidos:', items.length);
console.log('Eventos detectados con datos:', eventos.length);

if (eventos.length === 0) {
  console.log('✓ Horario DISPONIBLE');
  return [{
    json: {
      disponible: true,
      mensaje: 'El horario está disponible'
    }
  }];
} else {
  console.log('✗ Horario NO DISPONIBLE');
  eventos.forEach((ev, idx) => {
    console.log(`Evento ${idx + 1}:`, JSON.stringify(ev, null, 2));
  });
  return [{
    json: {
      disponible: false,
      mensaje: 'El horario no está disponible, ya existe una cita agendada'
    }
  }];
}

// Nodo Code: Normalizar rango de fechas para Google Calendar (Costa Rica UTC-6)

const item = $input.first().json;

/*
  Entradas esperadas:
  {
    "calendar_id": "...",
    "timeMin": "2025-12-11T10:00:00",
    "timeMax": "2025-12-11T11:00:00"
  }

  Google Calendar exige RFC3339 con offset, ej:
  2025-12-11T10:00:00-06:00
*/

// Costa Rica -> UTC-6
const offset = '-06:00';

// Añadimos el offset manualmente
const timeMinFormatted = item.timeMin + offset;
const timeMaxFormatted = item.timeMax + offset;

// Devolvemos el objeto para que lo consuma el nodo "Obtener eventos"
return [{
  json: {
    calendar_id: item.calendar_id,
    timeMin: timeMinFormatted,
    timeMax: timeMaxFormatted,
  }
}];
